#!/usr/bin/env node
/* tools/apply_app.mjs - v5.6 APP (+ sandbox fix) - 2026-09-24
 *   Works from EITHER starting state: main after v5.5, or main with the first
 *   apply_app.mjs already run. Adds the sandbox fix (guarded address rewrites).
 * SAFETY: whole-file replace, only from a known state (LF or CRLF); any other
 * state writes nothing; re-running skips what is installed.
 *   node tools/apply_app.mjs --dry-run
 *   node tools/apply_app.mjs
 */
import fs from "node:fs"; import crypto from "node:crypto"; import path from "node:path";
const DRY = process.argv.includes("--dry-run");
const sha = (b) => crypto.createHash("sha256").update(b).digest("hex");
const P = JSON.parse("[{\"file\": \"species/sickleswarm.js\", \"target\": \"2bd099374e7731a333e89eb97312b3069d1baca0bf5ba316a131e29123ff36e5\", \"bases\": [\"2516f737cbb72037cdabccf40acad11fcc067afd9f50b13ba3678f44a8b39f2c\", \"2bd099374e7731a333e89eb97312b3069d1baca0bf5ba316a131e29123ff36e5\"], \"b64\": \"\"}, {\"file\": \"zigverse_engine.html\", \"target\": \"1dc95df0a1647c676682c9f51d0e1071fc7a95732b0f045259b4aa595b92791b\", \"bases\": [\"8577ed1f18971c52c845aed123e08e02fdb72a3dab4f2981a3dd515152615d99\", \"cbb42273d1392f242fdb98fa0b124e0fcc8f4777f04149029ee29af51303f562\"], \"b64\": \"\"}, {\"file\": \"tools/bundle.mjs\", \"target\": \"03df45626cc08fe5d1e27a1b817749c15c85e6e30a62a6e17b683eac75b9ef30\", \"bases\": [\"03df45626cc08fe5d1e27a1b817749c15c85e6e30a62a6e17b683eac75b9ef30\", \"95ce85a901c1eac8bac04927582490f51682218650dde71a3d63cd8d6ad07fd6\"], \"b64\": \"\"}, {\"file\": \"tools/app_icon.png\", \"target\": \"df52db6e7432915da8af46f39513333526f27a251f4bbb3a660058d271de525d\", \"bases\": [\"ABSENT\", \"df52db6e7432915da8af46f39513333526f27a251f4bbb3a660058d271de525d\"], \"b64\": \"\"}, {\"file\": \"test/_touchboot.mjs\", \"target\": \"bf0a77cdaaf3739f20a81a24a0545bc8624ed32926681c1fcb4f7ac17d28fc2f\", \"bases\": [\"a8473a1eb4a0572fd200f173d4d5db957dfa2682055108edd948ff7fdce2ebe7\", \"bf0a77cdaaf3739f20a81a24a0545bc8624ed32926681c1fcb4f7ac17d28fc2f\"], \"b64\": \"\"}, {\"file\": \"test/mobile_ref.mjs\", \"target\": \"187384f7f4c515f36ef5b57373d254af51f642a09a51626e24c8799493f3024f\", \"bases\": [\"187384f7f4c515f36ef5b57373d254af51f642a09a51626e24c8799493f3024f\", \"dbf1510d0efca910d46a78e89269c0deb36c10a4c69ee30eced2616234724e6d\"], \"b64\": \"\"}, {\"file\": \"test/app_ref.mjs\", \"target\": \"0e31998c8f5790d19edc6c3e6af442533186bc0a3541b0253f1139ee33eebd2d\", \"bases\": [\"ABSENT\", \"f804aa62b35ee65599364c4a4e8e6595be334c9332229064d0e030c133b67401\"], \"b64\": \"\"}]");
const LOGS = [["2026-09-24 - v5.6 APP", ""], ["2026-09-24 - v5.6 sandbox fix", ""]].map(([m, b]) => [m, Buffer.from(b, "base64")]);
console.log("apply_app.mjs\n");
if (!fs.existsSync("species/sickleswarm.js") || !fs.existsSync("briefs/Session_Log.md")) {
  console.log("  FAIL  run this from the repo root (C:\\Users\\billy\\Zigverse)"); process.exit(1); }
let bad = 0; const plan = [];
for (const e of P) {
  const cur = fs.existsSync(e.file) ? fs.readFileSync(e.file) : null;
  /* Git on Windows may turn LF into CRLF when it touches a file — the same
     text, different bytes. Compare both ways so a clean folder is never refused. */
  const lf = cur ? sha(Buffer.from(cur.toString("utf8").replace(/\r\n/g, "\n"), "utf8")) : "ABSENT";
  const h = cur ? (e.bases.includes(lf) || lf === e.target ? lf : sha(cur)) : "ABSENT";
  if (h === e.target) { console.log("  SKIP  " + e.file.padEnd(26) + " already installed"); continue; }
  if (!e.bases.includes(h)) { console.log("  FAIL  " + e.file.padEnd(26) + " unrecognised state (" + h.slice(0, 12) + ") — local edits?"); bad++; continue; }
  const out = Buffer.from(e.b64, "base64");
  if (sha(out) !== e.target) { console.log("  FAIL  " + e.file + " payload corrupt"); bad++; continue; }
  plan.push([e.file, out]); console.log("  OK    " + e.file.padEnd(26) + (cur ? " recognised → will replace" : " new file"));
}
const log = fs.readFileSync("briefs/Session_Log.md", "utf8");
const needLogs = LOGS.filter(([m]) => !log.includes(m));   // each entry once, in order - works before OR after the first apply_app
for (const [m] of LOGS) console.log("  " + (needLogs.some(([k]) => k === m) ? "OK    Session_Log: \"" + m + "\" will be appended" : "SKIP  Session_Log: \"" + m + "\" already present"));
if (bad) { console.log("\n  Nothing written. " + bad + " file(s) not in a state this installer knows."); process.exit(1); }
if (DRY) { console.log("\n  DRY RUN — all checks pass, nothing written."); process.exit(0); }
for (const [f, out] of plan) {
  fs.mkdirSync(path.dirname(f), { recursive: true });
  fs.writeFileSync(f, out);
  if (sha(fs.readFileSync(f)) !== sha(out)) { console.log("  FAIL  write verify " + f); process.exit(1); }
  console.log("  WROTE " + f + "  sha256 " + sha(out).slice(0, 16) + "… verified");
}
for (const [m, b] of needLogs) { fs.appendFileSync("briefs/Session_Log.md", b); console.log("  WROTE Session_Log: \"" + m + "\""); }
console.log("\n  NEXT (Bill, eyeZ, PowerShell):");
console.log("    reference checks (expect 51 PASS), bundle with --app to dist\\Zigverse_v5_6_App.html,");
console.log("    boot_gate, node test\\_touchboot.mjs, then LAND.cmd — Glyph gives the lines.");
